/**
 * Exhaustive Game Tree Verifier for "Center Takes the Tie" Tic-Tac-Toe
 *
 * Traverses all reachable legal move sequences to verify:
 * 1. Zero draws exist in any legal line of play.
 * 2. Every legal sequence terminates in <= 9 moves.
 * 3. Exact counts of terminal game sequences, reachable states, and win reasons.
 * 4. Negative control comparison against standard tic-tac-toe (where draws exist).
 */

const WINNING_LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8], // Rows
  [0, 3, 6], [1, 4, 7], [2, 5, 8], // Columns
  [0, 4, 8], [2, 4, 6]             // Diagonals
];

const CENTER_INDEX = 4;

function checkLineWin(board) {
  for (let i = 0; i < WINNING_LINES.length; i++) {
    const [a, b, c] = WINNING_LINES[i];
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return { winner: board[a], line: [a, b, c] };
    }
  }
  return null;
}

function evaluateVariantTerminal(board, moveCount) {
  const lineResult = checkLineWin(board);
  if (lineResult) {
    return {
      isTerminal: true,
      winner: lineResult.winner,
      reason: 'line',
      line: lineResult.line
    };
  }

  if (moveCount === 9) {
    // Board is full. Center cell is occupied.
    const centerOwner = board[CENTER_INDEX];
    if (!centerOwner) {
      throw new Error('Center cell must be occupied on move 9');
    }
    return {
      isTerminal: true,
      winner: centerOwner,
      reason: 'center',
      line: null
    };
  }

  return { isTerminal: false, winner: null, reason: null, line: null };
}

function evaluateStandardTerminal(board, moveCount) {
  const lineResult = checkLineWin(board);
  if (lineResult) {
    return { isTerminal: true, winner: lineResult.winner, reason: 'line' };
  }
  if (moveCount === 9) {
    return { isTerminal: true, winner: null, reason: 'draw' };
  }
  return { isTerminal: false, winner: null, reason: null };
}

function runVerification() {
  console.log('=== Exhaustive Game Tree Verification ===');
  console.log('Starting traversal from empty board...\n');

  const stats = {
    totalSequences: 0,
    maxDepth: 0,
    xLineWins: 0,
    oLineWins: 0,
    xCenterWins: 0,
    oCenterWins: 0,
    draws: 0,
    distinctStates: new Set(),
    transitions: 0,
    depthDistribution: {}
  };

  const standardStats = {
    totalSequences: 0,
    draws: 0,
    xWins: 0,
    oWins: 0
  };

  function serializeBoard(board, player) {
    return board.map(c => c || '.').join('') + ':' + player;
  }

  function dfs(board, nextPlayer, depth) {
    const stateKey = serializeBoard(board, nextPlayer);
    stats.distinctStates.add(stateKey);

    const term = evaluateVariantTerminal(board, depth);
    if (term.isTerminal) {
      stats.totalSequences++;
      stats.maxDepth = Math.max(stats.maxDepth, depth);
      stats.depthDistribution[depth] = (stats.depthDistribution[depth] || 0) + 1;

      if (term.reason === 'line') {
        if (term.winner === 'X') stats.xLineWins++;
        else stats.oLineWins++;
      } else if (term.reason === 'center') {
        if (term.winner === 'X') stats.xCenterWins++;
        else stats.oCenterWins++;
      } else {
        stats.draws++;
      }
      return;
    }

    // Explore legal moves
    const opponent = nextPlayer === 'X' ? 'O' : 'X';
    for (let i = 0; i < 9; i++) {
      if (board[i] === null) {
        stats.transitions++;
        board[i] = nextPlayer;
        dfs(board, opponent, depth + 1);
        board[i] = null;
      }
    }
  }

  function dfsStandard(board, nextPlayer, depth) {
    const term = evaluateStandardTerminal(board, depth);
    if (term.isTerminal) {
      standardStats.totalSequences++;
      if (term.reason === 'draw') standardStats.draws++;
      else if (term.winner === 'X') standardStats.xWins++;
      else standardStats.oWins++;
      return;
    }

    const opponent = nextPlayer === 'X' ? 'O' : 'X';
    for (let i = 0; i < 9; i++) {
      if (board[i] === null) {
        board[i] = nextPlayer;
        dfsStandard(board, opponent, depth + 1);
        board[i] = null;
      }
    }
  }

  const initialBoard = Array(9).fill(null);

  const t0 = Date.now();
  dfs(initialBoard, 'X', 0);
  const variantDuration = Date.now() - t0;

  console.log(`Variant Traversal completed in ${variantDuration}ms.`);
  console.log('Running Standard Rules negative control...');
  const t1 = Date.now();
  dfsStandard(initialBoard, 'X', 0);
  const standardDuration = Date.now() - t1;
  console.log(`Standard Traversal completed in ${standardDuration}ms.\n`);

  console.log('--- Results: Center Takes the Tie ---');
  console.log(`Total Terminal Sequences (Paths): ${stats.totalSequences.toLocaleString()}`);
  console.log(`Distinct Reachable Board States:  ${stats.distinctStates.size.toLocaleString()}`);
  console.log(`Total Valid State Transitions:    ${stats.transitions.toLocaleString()}`);
  console.log(`Maximum Move Depth:               ${stats.maxDepth} (Bound: <= 9)`);
  console.log(`Total Draws:                      ${stats.draws} (MUST BE 0)`);
  console.log(`X Line Wins:                      ${stats.xLineWins.toLocaleString()}`);
  console.log(`O Line Wins:                      ${stats.oLineWins.toLocaleString()}`);
  console.log(`X Center Fallback Wins:           ${stats.xCenterWins.toLocaleString()}`);
  console.log(`O Center Fallback Wins:           ${stats.oCenterWins.toLocaleString()}`);
  console.log('\nSequences by Move Depth:');
  Object.keys(stats.depthDistribution).sort((a,b) => a - b).forEach(d => {
    console.log(`  Move ${d}: ${stats.depthDistribution[d].toLocaleString()} paths`);
  });

  console.log('\n--- Negative Control (Standard Tic-Tac-Toe) ---');
  console.log(`Total Standard Terminal Sequences: ${standardStats.totalSequences.toLocaleString()}`);
  console.log(`Standard X Wins:                  ${standardStats.xWins.toLocaleString()}`);
  console.log(`Standard O Wins:                  ${standardStats.oWins.toLocaleString()}`);
  console.log(`Standard Draws:                   ${standardStats.draws.toLocaleString()}`);

  // Invariant assertions
  if (stats.draws !== 0) {
    throw new Error(`CRITICAL FAILURE: Found ${stats.draws} draws in variant!`);
  }
  if (stats.maxDepth > 9) {
    throw new Error(`CRITICAL FAILURE: Max depth exceeded 9! Found ${stats.maxDepth}`);
  }
  if (stats.totalSequences !== standardStats.totalSequences) {
    throw new Error(`Path count mismatch: ${stats.totalSequences} vs ${standardStats.totalSequences}`);
  }
  if (stats.xCenterWins + stats.oCenterWins !== standardStats.draws) {
    throw new Error('Center wins must exactly partition standard draws!');
  }

  console.log('\n[PASS] All mathematical and formal termination invariants verified!');
}

runVerification();

/**
 * Pure Game Engine for "Center Takes the Tie" Tic-Tac-Toe
 *
 * Implements immutable state transitions, input validation, line victory detection,
 * and the center-square tiebreaker fallback on move 9.
 *
 * Zero external dependencies; compatible with both Browser and Node.js environments.
 */

(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    root.GameEngine = factory();
  }
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const WINNING_LINES = Object.freeze([
    Object.freeze([0, 1, 2]), // Row 1
    Object.freeze([3, 4, 5]), // Row 2
    Object.freeze([6, 7, 8]), // Row 3
    Object.freeze([0, 3, 6]), // Column 1
    Object.freeze([1, 4, 7]), // Column 2
    Object.freeze([2, 5, 8]), // Column 3
    Object.freeze([0, 4, 8]), // Diagonal 1
    Object.freeze([2, 4, 6])  // Diagonal 2
  ]);

  const CENTER_INDEX = 4;

  /**
   * Initializes a fresh, unplayed game state.
   * @returns {Object} Fresh game state
   */
  function createGame() {
    return Object.freeze({
      board: Object.freeze(Array(9).fill(null)),
      nextPlayer: 'X',
      winner: null,
      winReason: null,     // null | 'line' | 'center'
      winningLine: null,   // null | readonly [number, number, number]
      isTerminal: false,
      moveCount: 0,
      history: Object.freeze([])
    });
  }

  /**
   * Checks if any player has formed a three-in-a-row line.
   * @param {Array<string|null>} board
   * @returns {{ winner: string, line: readonly [number, number, number] } | null}
   */
  function checkLineWin(board) {
    for (let i = 0; i < WINNING_LINES.length; i++) {
      const line = WINNING_LINES[i];
      const [a, b, c] = line;
      if (board[a] && board[a] === board[b] && board[a] === board[c]) {
        return { winner: board[a], line: line };
      }
    }
    return null;
  }

  /**
   * Applies a move to the board, returning an immutable new state or an error.
   *
   * @param {Object} state - Current game state
   * @param {number} index - 0-based cell index (0..8)
   * @returns {{ ok: boolean, state: Object, error: string|null }}
   */
  function applyMove(state, index) {
    if (!state || typeof state !== 'object') {
      return { ok: false, state: null, error: 'INVALID_STATE' };
    }

    if (state.isTerminal) {
      return { ok: false, state, error: 'GAME_OVER' };
    }

    if (!Number.isInteger(index)) {
      return { ok: false, state, error: 'INVALID_INDEX' };
    }

    if (index < 0 || index > 8) {
      return { ok: false, state, error: 'OUT_OF_BOUNDS' };
    }

    if (state.board[index] !== null) {
      return { ok: false, state, error: 'CELL_OCCUPIED' };
    }

    // Clone and place mark
    const newBoard = state.board.slice();
    newBoard[index] = state.nextPlayer;
    const newMoveCount = state.moveCount + 1;
    const newHistory = state.history.concat(index);

    // 1. Check for immediate line completion
    const lineResult = checkLineWin(newBoard);
    if (lineResult) {
      const terminalState = Object.freeze({
        board: Object.freeze(newBoard),
        nextPlayer: null,
        winner: lineResult.winner,
        winReason: 'line',
        winningLine: lineResult.line,
        isTerminal: true,
        moveCount: newMoveCount,
        history: Object.freeze(newHistory)
      });
      return { ok: true, state: terminalState, error: null };
    }

    // 2. Full board reached without a line completion (Move 9 fallback)
    if (newMoveCount === 9) {
      const centerOwner = newBoard[CENTER_INDEX];
      const terminalState = Object.freeze({
        board: Object.freeze(newBoard),
        nextPlayer: null,
        winner: centerOwner,
        winReason: 'center',
        winningLine: null,
        isTerminal: true,
        moveCount: newMoveCount,
        history: Object.freeze(newHistory)
      });
      return { ok: true, state: terminalState, error: null };
    }

    // 3. Ongoing game: alternate turns
    const nextPlayer = state.nextPlayer === 'X' ? 'O' : 'X';
    const nextState = Object.freeze({
      board: Object.freeze(newBoard),
      nextPlayer: nextPlayer,
      winner: null,
      winReason: null,
      winningLine: null,
      isTerminal: false,
      moveCount: newMoveCount,
      history: Object.freeze(newHistory)
    });

    return { ok: true, state: nextState, error: null };
  }

  return {
    WINNING_LINES,
    CENTER_INDEX,
    createGame,
    checkLineWin,
    applyMove
  };
});

const test = require('node:test');
const assert = require('node:assert/strict');
const engine = require('../src/engine.js');

test('Engine: Initial Game State', () => {
  const state = engine.createGame();
  assert.equal(state.board.length, 9);
  assert.ok(state.board.every(cell => cell === null));
  assert.equal(state.nextPlayer, 'X');
  assert.equal(state.winner, null);
  assert.equal(state.winReason, null);
  assert.equal(state.winningLine, null);
  assert.equal(state.isTerminal, false);
  assert.equal(state.moveCount, 0);
  assert.deepEqual(state.history, []);
  assert.ok(Object.isFrozen(state));
  assert.ok(Object.isFrozen(state.board));
});

test('Engine: Turn Alternation and State Immutability', () => {
  const state0 = engine.createGame();
  const res1 = engine.applyMove(state0, 0);
  assert.equal(res1.ok, true);
  assert.equal(res1.error, null);
  assert.equal(res1.state.board[0], 'X');
  assert.equal(res1.state.nextPlayer, 'O');
  assert.equal(res1.state.moveCount, 1);
  assert.deepEqual(res1.state.history, [0]);

  // Original state0 must remain untouched
  assert.equal(state0.board[0], null);
  assert.equal(state0.nextPlayer, 'X');
  assert.equal(state0.moveCount, 0);

  const res2 = engine.applyMove(res1.state, 4);
  assert.equal(res2.ok, true);
  assert.equal(res2.state.board[4], 'O');
  assert.equal(res2.state.nextPlayer, 'X');
  assert.equal(res2.state.moveCount, 2);
  assert.deepEqual(res2.state.history, [0, 4]);
});

test('Engine: Input Validation & Rejections', () => {
  let { state } = engine.applyMove(engine.createGame(), 0);

  // CELL_OCCUPIED
  const occupiedRes = engine.applyMove(state, 0);
  assert.equal(occupiedRes.ok, false);
  assert.equal(occupiedRes.error, 'CELL_OCCUPIED');
  assert.equal(occupiedRes.state, state);

  // OUT_OF_BOUNDS
  const outLow = engine.applyMove(state, -1);
  assert.equal(outLow.ok, false);
  assert.equal(outLow.error, 'OUT_OF_BOUNDS');

  const outHigh = engine.applyMove(state, 9);
  assert.equal(outHigh.ok, false);
  assert.equal(outHigh.error, 'OUT_OF_BOUNDS');

  // INVALID_INDEX
  const notInt = engine.applyMove(state, 1.5);
  assert.equal(notInt.ok, false);
  assert.equal(notInt.error, 'INVALID_INDEX');

  const stringIdx = engine.applyMove(state, '0');
  assert.equal(stringIdx.ok, false);
  assert.equal(stringIdx.error, 'INVALID_INDEX');

  const undefIdx = engine.applyMove(state, undefined);
  assert.equal(undefIdx.ok, false);
  assert.equal(undefIdx.error, 'INVALID_INDEX');
});

test('Engine: Early Line Win (Horizontal row)', () => {
  // Moves: X:0, O:3, X:1, O:4, X:2 -> X wins on top row [0, 1, 2]
  let state = engine.createGame();
  state = engine.applyMove(state, 0).state; // X
  state = engine.applyMove(state, 3).state; // O
  state = engine.applyMove(state, 1).state; // X
  state = engine.applyMove(state, 4).state; // O
  const winMove = engine.applyMove(state, 2); // X

  assert.equal(winMove.ok, true);
  const finalState = winMove.state;
  assert.equal(finalState.isTerminal, true);
  assert.equal(finalState.winner, 'X');
  assert.equal(finalState.winReason, 'line');
  assert.deepEqual(finalState.winningLine, [0, 1, 2]);
  assert.equal(finalState.nextPlayer, null);
  assert.equal(finalState.moveCount, 5);

  // Attempting move after game over
  const postWin = engine.applyMove(finalState, 8);
  assert.equal(postWin.ok, false);
  assert.equal(postWin.error, 'GAME_OVER');
});

test('Engine: Early Line Win for O (Diagonal)', () => {
  // Moves: X:0, O:4, X:1, O:2, X:8, O:6 -> O wins diagonal [2, 4, 6]
  let state = engine.createGame();
  state = engine.applyMove(state, 0).state; // X
  state = engine.applyMove(state, 4).state; // O (center)
  state = engine.applyMove(state, 1).state; // X
  state = engine.applyMove(state, 2).state; // O
  state = engine.applyMove(state, 8).state; // X
  const winMove = engine.applyMove(state, 6); // O

  assert.equal(winMove.ok, true);
  const finalState = winMove.state;
  assert.equal(finalState.isTerminal, true);
  assert.equal(finalState.winner, 'O');
  assert.equal(finalState.winReason, 'line');
  assert.deepEqual(finalState.winningLine, [2, 4, 6]);
});

test('Engine: Move 9 Line Win Precedence over Center Fallback', () => {
  // Board:
  // X O X
  // X O O
  // O X X
  // Move sequence where X completes a line on move 9:
  // 0:X, 1:O, 2:X, 4:O, 3:X, 5:O, 7:X, 6:O, 8:X
  // Check: X marks 0, 2, 3, 7, 8. O marks 1, 4, 5, 6.
  // Wait, does any line complete?
  // Let's create an explicit move 9 line win:
  // X O X
  // O O X
  // O X X (X completes right column: 2, 5, 8 on move 9)
  // X: 0, O: 1, X: 2, O: 3, X: 7, O: 4 (O takes center!), X: ?
  // Let's trace moves:
  // 1. X: 0
  // 2. O: 4 (O owns center)
  // 3. X: 2
  // 4. O: 1
  // 5. X: 5
  // 6. O: 3
  // 7. X: 7
  // 8. O: 6
  // 9. X: 8 -> X forms [2, 5, 8]!
  // At move 8, cells marked:
  // X: 0, 2, 5, 7
  // O: 4, 1, 3, 6
  // On move 9, cell 8 is played by X.
  // Right column is [2, 5, 8] which is all X!
  // Center is cell 4 owned by O.
  // Requirement: Line completion MUST take precedence over center owner O!
  let state = engine.createGame();
  const sequence = [0, 4, 2, 1, 5, 3, 7, 6, 8];
  sequence.forEach((cell, idx) => {
    const res = engine.applyMove(state, cell);
    assert.equal(res.ok, true, `Move ${idx + 1} at cell ${cell} should succeed`);
    state = res.state;
  });

  assert.equal(state.moveCount, 9);
  assert.equal(state.isTerminal, true);
  assert.equal(state.board[4], 'O'); // O owned center!
  assert.equal(state.winner, 'X');   // But X completed line [2, 5, 8]
  assert.equal(state.winReason, 'line');
  assert.deepEqual(state.winningLine, [2, 5, 8]);
});

test('Engine: Full Board Fallback — X owns Center', () => {
  // Classic draw board in normal tic-tac-toe:
  // X O X
  // X X O
  // O X O
  // Board:
  // 0:X, 1:O, 2:X
  // 3:X, 4:X, 5:O
  // 6:O, 7:X, 8:O
  // Lines:
  // Rows: XOX (no), XXO (no), OXO (no)
  // Cols: XXO (no), OXX (no), XOO (no)
  // Diags: XXO (no), X X O (no)
  // No lines anywhere!
  // X owns center (4).
  // Plays:
  // Move 1: X -> 0
  // Move 2: O -> 1
  // Move 3: X -> 4 (center)
  // Move 4: O -> 8
  // Move 5: X -> 2
  // Move 6: O -> 6
  // Move 7: X -> 3
  // Move 8: O -> 5
  // Move 9: X -> 7
  const moves = [0, 1, 4, 8, 2, 6, 3, 5, 7];
  let state = engine.createGame();
  moves.forEach(m => {
    state = engine.applyMove(state, m).state;
  });

  assert.equal(state.moveCount, 9);
  assert.equal(state.isTerminal, true);
  assert.equal(state.winner, 'X');
  assert.equal(state.winReason, 'center');
  assert.equal(state.winningLine, null);
  assert.equal(state.board[4], 'X');
});

test('Engine: Full Board Fallback — O owns Center', () => {
  // Board:
  // O X O
  // X O X
  // X O X
  // Wait, count of marks: in a 9-move game, X must have 5 marks, O has 4 marks.
  // Board with O in center and 5 X's, 4 O's, and no lines:
  // X X O (0:X, 1:X, 2:O)
  // O O X (3:O, 4:O, 5:X)
  // X O X (6:X, 7:O, 8:X)
  // Check lines:
  // Rows:
  // 0,1,2: X X O (no)
  // 3,4,5: O O X (no)
  // 6,7,8: X O X (no)
  // Cols:
  // 0,3,6: X O X (no)
  // 1,4,7: X O O (no)
  // 2,5,8: O X X (no)
  // Diagonals:
  // 0,4,8: X O X (no)
  // 2,4,6: O O X (no)
  // Total X: cells 0, 1, 5, 6, 8 (count: 5)
  // Total O: cells 2, 3, 4, 7 (count: 4)
  // Center: cell 4 is 'O'!
  // Let's verify a move sequence to reach this board:
  // 1. X: 0
  // 2. O: 4 (O takes center)
  // 3. X: 1
  // 4. O: 2
  // 5. X: 5
  // 6. O: 3
  // 7. X: 8
  // 8. O: 7
  // 9. X: 6
  const moves = [0, 4, 1, 2, 5, 3, 8, 7, 6];
  let state = engine.createGame();
  moves.forEach((m, idx) => {
    const res = engine.applyMove(state, m);
    assert.equal(res.ok, true, `Move ${idx + 1} at ${m} failed`);
    state = res.state;
  });

  assert.equal(state.moveCount, 9);
  assert.equal(state.isTerminal, true);
  assert.equal(state.board[4], 'O');
  assert.equal(state.winner, 'O');
  assert.equal(state.winReason, 'center');
  assert.equal(state.winningLine, null);
});

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --card-border: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --color-x: #38bdf8;
  --color-o: #fb923c;
  --accent-gold: #f59e0b;
  --win-color: #10b981;
  --cell-bg: #1e293b;
  --cell-hover: #334155;
  --cell-disabled: #0f172a;
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
  --shadow-lg: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1.5rem;
}

.app-container {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.app-header {
  text-align: center;
}

.app-header h1 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #38bdf8, #818cf8, #fb923c);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.subtitle strong {
  color: var(--accent-gold);
}

.rules-card {
  background-color: rgba(30, 41, 59, 0.7);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-md);
  padding: 0.9rem 1.1rem;
  position: relative;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
}

.rule-badge {
  display: inline-block;
  background-color: rgba(245, 158, 11, 0.15);
  color: var(--accent-gold);
  border: 1px solid rgba(245, 158, 11, 0.4);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 9999px;
  margin-bottom: 0.4rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.rule-summary {
  font-size: 0.85rem;
  line-height: 1.4;
  color: var(--text-muted);
}

.rule-summary strong {
  color: var(--text-main);
}

.game-area {
  background-color: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.25rem;
}

.status-panel {
  text-align: center;
  width: 100%;
}

.status-message {
  font-size: 1.35rem;
  font-weight: 700;
  min-height: 2rem;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
}

.status-detail {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

.player-x {
  color: var(--color-x);
}

.player-o {
  color: var(--color-o);
}

.board-wrapper {
  width: 100%;
  max-width: 340px;
  aspect-ratio: 1 / 1;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  gap: 10px;
  width: 100%;
  height: 100%;
}

.cell {
  background-color: var(--cell-bg);
  border: 2px solid var(--card-border);
  border-radius: var(--radius-md);
  font-size: 3rem;
  font-weight: 900;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  position: relative;
  transition: all 0.15s ease-in-out;
  color: var(--text-main);
  user-select: none;
}

.cell:hover:not([disabled]) {
  background-color: var(--cell-hover);
  border-color: #64748b;
  transform: translateY(-2px);
}

.cell:focus-visible {
  outline: 2px solid var(--color-x);
  outline-offset: 2px;
}

.cell[disabled] {
  cursor: default;
}

.cell.marked-x {
  color: var(--color-x);
  text-shadow: 0 0 16px rgba(56, 189, 248, 0.4);
}

.cell.marked-o {
  color: var(--color-o);
  text-shadow: 0 0 16px rgba(251, 146, 60, 0.4);
}

.center-cell {
  position: relative;
  border-style: dashed;
  border-color: rgba(245, 158, 11, 0.5);
}

.center-badge {
  position: absolute;
  top: 4px;
  right: 6px;
  font-size: 0.75rem;
  color: var(--accent-gold);
  opacity: 0.7;
}

.cell.winning-cell {
  background-color: rgba(16, 185, 129, 0.25);
  border-color: var(--win-color);
  animation: pulse-win 1.5s infinite alternate ease-in-out;
}

.cell.center-win {
  background-color: rgba(245, 158, 11, 0.25);
  border-color: var(--accent-gold);
  animation: pulse-center 1.5s infinite alternate ease-in-out;
}

@keyframes pulse-win {
  from { box-shadow: 0 0 8px rgba(16, 185, 129, 0.4); }
  to { box-shadow: 0 0 20px rgba(16, 185, 129, 0.8); }
}

@keyframes pulse-center {
  from { box-shadow: 0 0 8px rgba(245, 158, 11, 0.4); }
  to { box-shadow: 0 0 20px rgba(245, 158, 11, 0.8); }
}

.controls {
  width: 100%;
}

.btn-primary {
  width: 100%;
  padding: 0.8rem 1.5rem;
  font-size: 1rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: #ffffff;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px -1px rgba(37, 99, 235, 0.3);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #1d4ed8, #1e40af);
  transform: translateY(-1px);
  box-shadow: 0 6px 12px -2px rgba(37, 99, 235, 0.4);
}

.btn-primary:active {
  transform: translateY(0);
}

.game-info {
  display: flex;
  justify-content: space-between;
  width: 100%;
  padding-top: 0.75rem;
  border-top: 1px solid var(--card-border);
  font-size: 0.85rem;
}

.info-item {
  display: flex;
  gap: 0.4rem;
}

.info-label {
  color: var(--text-muted);
}

.info-value {
  font-weight: 700;
  color: var(--text-main);
}

.app-footer {
  text-align: center;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/**
 * Browser Controller for "Center Takes the Tie" Tic-Tac-Toe
 *
 * Coordinates DOM interactions with pure GameEngine transitions.
 */

(function () {
  'use strict';

  // State
  let gameState = null;

  // DOM Elements
  const boardEl = document.getElementById('board');
  const cells = Array.from(document.querySelectorAll('.cell'));
  const statusMsgEl = document.getElementById('status-message');
  const statusDetailEl = document.getElementById('status-detail');
  const moveCountEl = document.getElementById('move-count');
  const centerOwnerEl = document.getElementById('center-owner-display');
  const btnReset = document.getElementById('btn-reset');

  const CELL_NAMES = [
    'Top Left', 'Top Center', 'Top Right',
    'Middle Left', 'Center (Tiebreaker)', 'Middle Right',
    'Bottom Left', 'Bottom Center', 'Bottom Right'
  ];

  function initGame() {
    gameState = window.GameEngine.createGame();
    render();
  }

  function handleCellClick(e) {
    const cellBtn = e.target.closest('.cell');
    if (!cellBtn) return;

    const index = parseInt(cellBtn.getAttribute('data-index'), 10);
    if (isNaN(index)) return;

    // Apply move through pure engine
    const result = window.GameEngine.applyMove(gameState, index);
    if (!result.ok) {
      // Move rejected (e.g. cell occupied or game over)
      // Do nothing, state unchanged
      return;
    }

    gameState = result.state;
    render();
  }

  function render() {
    const { board, nextPlayer, winner, winReason, winningLine, isTerminal, moveCount } = gameState;

    // Render cells
    cells.forEach((cell, idx) => {
      const mark = board[idx];
      cell.classList.remove('marked-x', 'marked-o', 'winning-cell', 'center-win');

      if (mark) {
        // Retain badge if center cell
        if (idx === window.GameEngine.CENTER_INDEX) {
          cell.innerHTML = `${mark}<span class="center-badge" title="Full-board Tiebreaker Owner">★</span>`;
        } else {
          cell.textContent = mark;
        }
        cell.classList.add(mark === 'X' ? 'marked-x' : 'marked-o');
        cell.disabled = true;
        cell.setAttribute('aria-label', `${CELL_NAMES[idx]} square, marked with ${mark}`);
      } else {
        if (idx === window.GameEngine.CENTER_INDEX) {
          cell.innerHTML = `<span class="center-badge" title="Full-board Tiebreaker Owner">★</span>`;
        } else {
          cell.textContent = '';
        }
        cell.disabled = isTerminal;
        cell.setAttribute('aria-label', `${CELL_NAMES[idx]} square, empty`);
      }
    });

    // Highlight win indicators
    if (isTerminal && winner) {
      if (winReason === 'line' && winningLine) {
        winningLine.forEach(idx => {
          cells[idx].classList.add('winning-cell');
        });
      } else if (winReason === 'center') {
        cells[window.GameEngine.CENTER_INDEX].classList.add('center-win');
      }
    }

    // Render status panel
    if (!isTerminal) {
      const playerClass = nextPlayer === 'X' ? 'player-x' : 'player-o';
      statusMsgEl.innerHTML = `Turn: <span class="${playerClass}">Player ${nextPlayer}</span>`;
      statusDetailEl.textContent = 'Place your mark in an empty square.';
    } else {
      const winnerClass = winner === 'X' ? 'player-x' : 'player-o';
      if (winReason === 'line') {
        statusMsgEl.innerHTML = `<span class="${winnerClass}">Player ${winner}</span> Wins!`;
        statusDetailEl.textContent = 'Three marks completed in a row.';
      } else if (winReason === 'center') {
        statusMsgEl.innerHTML = `<span class="${winnerClass}">Player ${winner}</span> Wins!`;
        statusDetailEl.textContent = 'Board is full without a line — victory awarded to Center square owner.';
      }
    }

    // Render move counter & center owner
    moveCountEl.textContent = `${moveCount} / 9`;
    const centerMark = board[window.GameEngine.CENTER_INDEX];
    if (centerMark) {
      centerOwnerEl.textContent = `Player ${centerMark}`;
      centerOwnerEl.className = `info-value ${centerMark === 'X' ? 'player-x' : 'player-o'}`;
    } else {
      centerOwnerEl.textContent = 'Unclaimed';
      centerOwnerEl.className = 'info-value';
    }
  }

  // Event Listeners
  boardEl.addEventListener('click', handleCellClick);
  btnReset.addEventListener('click', initGame);

  // Initialize on script load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initGame);
  } else {
    initGame();
  }
})();
